package org.jellyfin.androidtv.bestv
import org.jellyfin.sdk.api.client.util.ApiSerializer
import org.jellyfin.sdk.model.api.*
import kotlinx.serialization.json.*
private fun item(id: Int, extra: String="", type: String="Movie"): BaseItemDto {
 val raw="""{"Id":"00000000-0000-0000-0000-${id.toString().padStart(12,'0')}","Type":"$type","Name":"Movie ${id.toString().padStart(3,'0')}"$extra}"""
 val obj=ApiSerializer.json.parseToJsonElement(raw).jsonObject
 val normal=buildJsonObject {obj.forEach { (k,v)->put(k,v) };obj["UserData"]?.jsonObject?.let {user->put("UserData",buildJsonObject {put("PlayCount",0);put("IsFavorite",false);put("Key",id.toString());put("ItemId",obj.getValue("Id"));put("Played",false);put("PlaybackPositionTicks",0);user.forEach { (k,v)->put(k,v) }})}}
 return ApiSerializer.json.decodeFromJsonElement<BaseItemDto>(normal)
}
private fun durationSource(ticks: Long): MediaSourceInfo {
 val fields=ApiSerializer.json.parseToJsonElement("""{"Protocol":"File","Type":"Default","IsRemote":false,"ReadAtNativeFramerate":false,"IgnoreDts":false,"IgnoreIndex":false,"GenPtsInput":false,"SupportsTranscoding":false,"SupportsDirectStream":false,"SupportsDirectPlay":true,"IsInfiniteStream":false,"RequiresOpening":false,"RequiresClosing":false,"RequiresLooping":false,"SupportsProbing":true,"TranscodingSubProtocol":"http","HasSegments":false}""").jsonObject
 return ApiSerializer.json.decodeFromJsonElement(buildJsonObject {fields.forEach {(key,value)->put(key,value)};put("RunTimeTicks",ticks)})
}
fun main(){
 var checks=0
 fun verify(name: String,ok: Boolean){check(ok){name};checks++;println("PASS $name")}
 val all=(1..86).map {item(it,",\"CommunityRating\":${it/10.0},\"Genres\":[\"${if(it%2==0)"Drama" else "Action"}\"],\"ProductionYear\":${2000+it%3}")}
 val q=LibraryBrowse.Query()
 verify("default ordering is name ascending",q.sort==LibraryBrowse.Sort.NAME&&q.ascending)
 verify("complete filtered scope before page",LibraryBrowse.select(all,q.copy(genre="Drama")).size==43)
 verify("rating sort reaches item outside first page",LibraryBrowse.select(all,q.copy(sort=LibraryBrowse.Sort.RATING,ascending=false)).first().id==all.last().id)
 verify("year and genre combine",LibraryBrowse.select(all,q.copy(genre="Drama",year=2001)).all {it.productionYear==2001&&"Drama" in it.genres.orEmpty()})
 verify("paging preserves exact total",LibraryBrowse.select(all,q).drop(60).take(60).size==26)
 val unseen=item(101,",\"UserData\":{\"Played\":false}");val watching=item(102,",\"UserData\":{\"PlaybackPositionTicks\":10000,\"Played\":false}")
 val finished=item(103,",\"UserData\":{\"Played\":true,\"LastPlayedDate\":\"2026-11-01T00:00:00Z\"}")
 val unknown=item(104)
 val states=listOf(unseen,watching,finished,unknown)
 verify("missing user state is not unseen",unknown !in LibraryBrowse.select(states,q.copy(state=LibraryBrowse.State.UNSEEN)))
 verify("rating threshold excludes missing rating",LibraryBrowse.select(all+unknown,q.copy(minimumRating=8.0)).all {(it.communityRating ?: -1f)>=8f})
 verify("unknown year is selectable",LibraryBrowse.select(all+unknown,q.copy(unknownYear=true))==listOf(unknown))
 verify("server favorites remain isolated",LibraryBrowse.select(states+item(105,",\"UserData\":{\"IsFavorite\":true}"),q.copy(favorites=true)).single().id==item(105).id)
 verify("known movie progress",LibraryBrowse.progress(watching)==null)
 verify("played progress is complete",LibraryBrowse.progress(finished)==1.0)

 verify("unseen excludes finished and partial",LibraryBrowse.select(states,q.copy(state=LibraryBrowse.State.UNSEEN))==listOf(unseen))
 verify("watching excludes finished",LibraryBrowse.select(states,q.copy(state=LibraryBrowse.State.WATCHING))==listOf(watching))
 verify("finished filter",LibraryBrowse.select(states,q.copy(state=LibraryBrowse.State.FINISHED))==listOf(finished))
 verify("recent includes finished",LibraryBrowse.select(states,q.copy(recent=true)).contains(finished))
 val episodes=listOf(item(201,",\"SeriesId\":\"00000000-0000-0000-0000-000000000999\",\"UserData\":{\"LastPlayedDate\":\"2026-11-01T00:00:00Z\"}","Episode"),item(202,",\"SeriesId\":\"00000000-0000-0000-0000-000000000999\",\"UserData\":{\"LastPlayedDate\":\"2026-11-02T00:00:00Z\"}","Episode"))
 verify("recent aggregates latest actual episode",LibraryBrowse.select(episodes,q.copy(recent=true)).single().id==episodes.last().id)
 verify("episodes excluded from movie/series home",LibraryBrowse.select(episodes,q).isEmpty())
 val series=item(999,",\"UserData\":{\"Played\":false}","Series")
 val one=episodes[0].copy(userData=episodes[0].userData!!.copy(played=true))
 val two=episodes[1].copy(userData=episodes[1].userData!!.copy(played=false,playbackPositionTicks=5000))
 val aggregate=LibraryBrowse.select(listOf(series,one,two),q).single()
 verify("series progress uses actual available episode count",LibraryBrowse.progress(aggregate)==0.5)
 verify("series partially watched is watching",LibraryBrowse.watching(aggregate))
 verify("history restores the series identity",LibraryBrowse.select(listOf(series,one,two),q.copy(recent=true)).single().id==series.id)
 verify("last played episode does not complete series",aggregate.userData?.played==false)
 val authoritative=series.copy(recursiveItemCount=10,userData=series.userData!!.copy(unplayedItemCount=5))
 val missingEpisodeData=episodes.map {it.copy(userData=null)}
 val preserved=LibraryBrowse.select(listOf(authoritative)+missingEpisodeData,q).single()
 verify("series server progress survives absent episode user data",preserved.recursiveItemCount==10&&preserved.userData?.unplayedItemCount==5&&LibraryBrowse.watching(preserved)&&LibraryBrowse.progress(preserved)==0.5)
 val unknownSeries=series.copy(recursiveItemCount=null)
 verify("series denominator missing never invents progress",LibraryBrowse.progress(unknownSeries)==null)
 val equalNames=listOf(item(812,",\"CommunityRating\":8.0").copy(name="Zebra",sortName=null),item(811,",\"CommunityRating\":8.0").copy(name="Alpha",sortName=null))
 verify("rating ties use name then stable id",LibraryBrowse.select(equalNames,q.copy(sort=LibraryBrowse.Sort.RATING)).first().name=="Alpha")

 for(asc in listOf(false,true))verify("unknown rating remains last ($asc)",LibraryBrowse.select(listOf(unseen)+all,q.copy(sort=LibraryBrowse.Sort.RATING,ascending=asc)).last().id==unseen.id)
 val uhd=item(301,",\"MediaStreams\":[{\"Type\":\"Video\",\"IsInterlaced\":false,\"IsDefault\":false,\"IsForced\":false,\"IsHearingImpaired\":false,\"IsExternal\":false,\"IsTextSubtitleStream\":false,\"SupportsExternalStream\":false,\"Index\":0,\"Width\":3840,\"Height\":1606}],\"ProductionLocations\":[\"France\"]")
 val hd=item(302,",\"MediaStreams\":[{\"Type\":\"Video\",\"IsInterlaced\":false,\"IsDefault\":false,\"IsForced\":false,\"IsHearingImpaired\":false,\"IsExternal\":false,\"IsTextSubtitleStream\":false,\"SupportsExternalStream\":false,\"Index\":0,\"Width\":1920,\"Height\":808}],\"ProductionLocations\":[\"China\"]")
 verify("cropped 4K uses actual width",LibraryBrowse.resolution(uhd)==2160)
 verify("cropped 1080 uses actual width",LibraryBrowse.resolution(hd)==1080)
 verify("unknown resolution absent",LibraryBrowse.resolution(unseen)==null)
 verify("card quality preserves cropped source tier",LibraryBrowse.quality(uhd)=="4K"&&LibraryBrowse.quality(hd)=="1080p")
 verify("card quality hides missing dimensions",LibraryBrowse.quality(unseen)==null)
 val video=hd.mediaStreams!!.first()
 verify("card quality distinguishes actual 8K and 1440p",LibraryBrowse.quality(hd.copy(mediaStreams=listOf(video.copy(width=7680,height=4320))))=="8K"&&LibraryBrowse.quality(hd.copy(mediaStreams=listOf(video.copy(width=2560,height=1440))))=="1440p")
 verify("small sources are not labelled 480p",LibraryBrowse.quality(hd.copy(mediaStreams=listOf(video.copy(width=640,height=360))))=="360p")
 verify("audio dimensions never become video quality",LibraryBrowse.quality(hd.copy(mediaStreams=listOf(video.copy(type=MediaStreamType.AUDIO))))==null)
 verify("quality reads media source streams",LibraryBrowse.quality(unseen.copy(mediaSources=listOf(durationSource(1).copy(mediaStreams=listOf(video)))))=="1080p")
 val seriesForQuality=item(399,type="Series")
 val episodeForQuality=uhd.copy(type=BaseItemKind.EPISODE,seriesId=seriesForQuality.id)
 verify("series quality uses only its actual episodes",LibraryBrowse.quality(seriesForQuality,listOf(episodeForQuality))=="4K"&&LibraryBrowse.quality(seriesForQuality,listOf(episodeForQuality.copy(seriesId=unseen.id)))==null)
 verify("resolution filters actual stream",LibraryBrowse.select(listOf(uhd,hd,unseen),q.copy(resolution=2160))==listOf(uhd))
 verify("region filters explicit production location",LibraryBrowse.select(listOf(uhd,hd),q.copy(region="China"))==listOf(hd))
 verify("absent region has no invented value",LibraryBrowse.regions(unseen).isEmpty())
 val first=LibraryBrowse.page(all,0,6);verify("first page range and disabled previous",first.range=="1-6"&&!first.previous&&first.next)
 val last=LibraryBrowse.page(all,84,6);verify("last page range and disabled next",last.range=="85-86"&&last.previous&&!last.next)
 verify("outdated page clamps after filtering",LibraryBrowse.page(all.take(2),84,6).range=="1-2")
 verify("empty range never claims item one",LibraryBrowse.page(emptyList(),60,6).range=="0-0")
 verify("large text page contains five posters",LibraryBrowse.page(all,0,5).items.size==5)
 val namedMovie=item(401,",\"OriginalTitle\":\"Film Alias\"")
 val namedSeries=item(402,type="Series")
 val namedLive=item(403,type="TvChannel")
 val namedAudio=item(404,type="Audio")
 val names=listOf(namedMovie,namedSeries,namedLive,namedAudio)
 verify("media search excludes live and audio",LibraryBrowse.search(names,"Movie").size==2)
 verify("movie search preserves category",LibraryBrowse.search(names,"Movie",BaseItemKind.MOVIE)==listOf(namedMovie))
 verify("series search preserves category",LibraryBrowse.search(names,"Movie",BaseItemKind.SERIES)==listOf(namedSeries))
 verify("search original title case insensitive",LibraryBrowse.search(names,"film ALIAS")==listOf(namedMovie))
 verify("blank search does not dump catalog",LibraryBrowse.search(names,"  ").isEmpty())
 verify("collection search cannot access outside snapshot",LibraryBrowse.search(listOf(namedSeries),"Film Alias").isEmpty())
 val early=item(501,",\"PremiereDate\":\"2025-01-02T00:00:00Z\",\"DateCreated\":\"2026-11-01T00:00:00Z\"")
 val late=item(502,",\"PremiereDate\":\"2025-12-02T00:00:00Z\",\"DateCreated\":\"2026-11-04T00:00:00Z\"")
 verify("release sorting distinguishes dates within a year",LibraryBrowse.select(listOf(late,early),q.copy(sort=LibraryBrowse.Sort.YEAR,ascending=true))==listOf(early,late))
 verify("recent entry uses actual added date across full scope",LibraryBrowse.select(listOf(early,unseen,late),LibraryPageLayout.Entry.RECENT.query())==listOf(late,early,unseen))
 for(asc in listOf(false,true))verify("unknown release date trails known ($asc)",LibraryBrowse.select(listOf(early,unseen,late),q.copy(sort=LibraryBrowse.Sort.YEAR,ascending=asc)).last()==unseen)
 val badDuration=item(601,",\"RunTimeTicks\":1080000000").copy(mediaSources=listOf(durationSource(64_500_000_000L)))
 verify("source duration overrides incorrect 108-second item duration",LibraryMetadata.durationTicks(badDuration)==64_500_000_000L)
 verify("forty minutes into 107m30s is 37.2 percent, not complete",kotlin.math.abs(LibraryMetadata.progress(badDuration,2_400_000L)-0.37209302325581395)<0.000001)
 verify("progress uses milliseconds against ticks",LibraryMetadata.progress(item(602,",\"RunTimeTicks\":72000000000"),1_800_000L)==0.25)
 verify("progress is bounded at both ends",LibraryMetadata.progress(badDuration,-100L)==0.0&&LibraryMetadata.progress(badDuration,9_000_000L)==1.0)
 verify("unknown duration does not invent progress",LibraryMetadata.durationTicks(unseen)==null&&LibraryMetadata.progress(unseen,2_400_000L)==0.0)
 verify("invalid source duration falls back to valid item duration",LibraryMetadata.durationTicks(item(603,",\"RunTimeTicks\":72000000000").copy(mediaSources=listOf(durationSource(0L))))==72_000_000_000L)
 println("$checks library browse checks passed")
}
